def icon(
    name: str,
    size: int = 18,
    color: str = "currentColor",
    extra_style: str = "",
) -> str:
    """Return an inline SVG string for *name*."""
    path = _P.get(name, _P["chart-bar"])
    style = f"display:inline-block;vertical-align:middle;flex-shrink:0;{extra_style}"
    return (
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{size}" height="{size}" '
        f'viewBox="0 0 24 24" fill="none" stroke="{color}" stroke-width="1.8" '
        f'style="{style}">{path}</svg>'
    )
